def unit_text(unit):
    raw=unit.get('text','')
    if not isinstance(raw,str):
        raw=str(raw)
    return raw

def any_in(text,phrases):
    for phrase in phrases:
        if phrase in text:
            return True
    return False

def personnel_reference(text):
    return any_in(text,['employee','contractor','consultant','agent','representative','official','director','officer','adviser','advisor','accountant'])

def disclosure_marker(text):
    return any_in(text,['may disclose','may be disclosed','may share','restrict disclosure','restrict access','except in confidence','except to such'])

def disclosure_governor(text):
    if text.endswith(':') and any_in(text,['may disclose','may be disclosed','following persons','following entities']):
        return True
    return any_in(text,['following are deemed confidential information','following shall be deemed confidential information'])

def find_disclosure_governor(spans,index):
    j=index-1
    distance=0
    while j>=0 and distance<20:
        text=unit_text(spans[j]).casefold().strip()
        if disclosure_governor(text):
            return j
        if any_in(text,['non-disclosure','remedies','governing law','entire agreement']) and not text.startswith(''):
            return -1
        j-=1
        distance+=1
    return -1

def disclosure_windows(spans):
    out=[]
    i=0
    while i<len(spans):
        text=unit_text(spans[i]).casefold()
        if personnel_reference(text):
            governor=-1
            if not disclosure_marker(text):
                governor=find_disclosure_governor(spans,i)
            ids=[]
            if disclosure_marker(text):
                ids.append(spans[i].get('id'))
            elif governor>=0:
                ids.append(spans[governor].get('id'))
                ids.append(spans[i].get('id'))
            if ids:
                out.append({'id':'personnel_window_'+str(spans[i].get('id')),'unit_ids':ids})
        i+=1
    return out

def disposal_action(text):
    return ('confidential information' in text or 'such confidential information' in text) and ('return' in text or 'destroy' in text or 'destruct' in text)

def endpoint_trigger(text):
    return any_in(text,['termination','expiration','completion of the purpose','business relationship is not entered','service terminates'])

def request_trigger(text):
    return 'request' in text

def disposal_windows(spans):
    out=[]
    i=0
    while i<len(spans):
        text=unit_text(spans[i]).casefold().strip()
        if disposal_action(text):
            ids=[spans[i].get('id')]
            has_trigger=endpoint_trigger(text) or request_trigger(text)
            if not has_trigger or text.endswith(':'):
                j=i+1
                steps=0
                while j<len(spans) and steps<4:
                    child=unit_text(spans[j]).casefold()
                    if endpoint_trigger(child) or request_trigger(child):
                        ids.append(spans[j].get('id'))
                        has_trigger=True
                    elif has_trigger:
                        break
                    j+=1
                    steps+=1
            if has_trigger:
                out.append({'id':'disposal_window_'+str(spans[i].get('id')),'unit_ids':ids})
        i+=1
    return out

def add_unresolved(out,message):
    if message not in out:
        out.append(message)

def add_statement(out,term,ids):
    for statement in out:
        if statement.get('term')==term:
            return
    out.append({'term':term,'support_ids':ids})

def make_union(items):
    if len(items)==1:
        return items[0]
    value=items[len(items)-1]
    i=len(items)-2
    while i>=0:
        value=['participant_union',items[i],value]
        i-=1
    return value

def make_bundle(items):
    if len(items)==1:
        return items[0]
    value=items[len(items)-1]
    i=len(items)-2
    while i>=0:
        value=['information_bundle',items[i],value]
        i-=1
    return value

def window_text(ids,byid):
    parts=[]
    for unit_id in ids:
        unit=byid.get(unit_id)
        if unit is not None:
            parts.append(unit_text(unit))
    return ' '.join(parts)

def exact_grounding(answer,ids,byid):
    for item in answer.get('evidence',[]):
        unit_id=item.get('unit_id')
        if unit_id not in ids:
            continue
        unit=byid.get(unit_id)
        if unit is None:
            continue
        quote=item.get('quote','')
        if isinstance(quote,str) and quote and quote in unit_text(unit):
            return True
    return False

def recipient_terms(text):
    owner=['receiving_party']
    items=[]
    if 'employee' in text:
        items.append(['employees_of',owner])
    if 'contractor' in text:
        items.append(['independent_contractors_of',owner])
    if 'consultant' in text:
        items.append(['consultants_of',owner])
    if 'agent' in text:
        items.append(['agents_of',owner])
    if 'director' in text:
        items.append(['directors_of',owner])
    if 'officer' in text:
        items.append(['officers_of',owner])
    if any_in(text,['professional adviser','professional advisor']):
        items.append(['professional_advisors_of',owner])
    if any_in(text,['legal adviser','legal advisor','attorney']):
        items.append(['legal_advisors_of',owner])
    if 'accountant' in text:
        items.append(['accountants_of',owner])
    unique=[]
    for item in items:
        if item not in unique:
            unique.append(item)
    return unique

def permission_condition(text):
    need=any_in(text,['need to know','need-to-know','need-to know'])
    bound=any_in(text,['written confidentiality agreement','written confidentiality agreements','subject to written confidentiality','bound by obligations of confidentiality','treat the confidential information in accordance with this agreement','advise such employees and/or consultants of the obligations assumed herein','obligated to protect'])
    if need and bound:
        return ['and_condition',['need_to_know','source-stated need to know'],['confidentiality_bound','source-stated confidentiality obligation']]
    return None

def has_existing_disposal(statements,action_id):
    for statement in statements:
        term=statement.get('term')
        if isinstance(term,list) and term and term[0]=='disposal_obligation' and action_id in statement.get('support_ids',[]):
            return True
    return False

def disposal_information(action_text,split_clause):
    items=[['confidential_information']]
    if not split_clause and ('copy' in action_text or 'copies' in action_text):
        items.append(['copies_of',['confidential_information']])
    if not split_clause and any_in(action_text,['notes','extracts','analyses','studies','summaries','records and reproductions','abstracts']):
        items.append(['derivative_materials_of',['confidential_information']])
    return make_bundle(items)

def endpoint_term(text):
    if any_in(text,['termination of service','service terminates']):
        return ['service_termination']
    if any_in(text,['termination','expiration']):
        return ['agreement_termination']
    return ['purpose_completion']

def trigger_from_choice(choice,text):
    endpoint=endpoint_term(text)
    request=['request_by',['disclosing_party']]
    if choice=='endpoint_only':
        return endpoint
    if choice=='request_only':
        return request
    if choice=='endpoint_or_request':
        return ['trigger_alternative',endpoint,request]
    return None

def apply(inputs,premises):
    spans=inputs.get('source_spans',[])
    source_output=inputs.get('source_output',{})
    statements=[]
    for statement in source_output.get('statements',[]):
        statements.append(statement)
    unresolved=[]
    for message in source_output.get('unresolved',[]):
        add_unresolved(unresolved,message)
    byid={}
    for unit in spans:
        byid[unit.get('id')]=unit
    answers={}
    for answer in inputs.get('semantic_answers',[]):
        answers[answer.get('id')]=answer
    for window in disclosure_windows(spans):
        query_id=window.get('id')
        ids=window.get('unit_ids',[])
        answer=answers.get(query_id)
        if answer is None:
            add_unresolved(unresolved,'Personnel disclosure window '+query_id+' was not semantically resolved.')
            continue
        choice=answer.get('choice')
        if choice=='nonoperative_reference':
            continue
        if choice!='operative_permission':
            add_unresolved(unresolved,'Personnel disclosure window '+query_id+' remains unknown.')
            continue
        if not exact_grounding(answer,ids,byid):
            add_unresolved(unresolved,'Personnel disclosure window '+query_id+' lacks exact current evidence.')
            continue
        text=window_text(ids,byid).casefold()
        recipients=recipient_terms(text)
        condition=permission_condition(text)
        if not recipients or condition is None or not disclosure_marker(text):
            add_unresolved(unresolved,'Personnel disclosure window '+query_id+' lacks a complete source-grounded permission structure.')
            continue
        term=['permission',['receiving_party'],['disclose',['confidential_information'],make_union(recipients)],condition]
        add_statement(statements,term,ids)
    for window in disposal_windows(spans):
        query_id=window.get('id')
        ids=window.get('unit_ids',[])
        if not ids:
            continue
        action_id=ids[0]
        if has_existing_disposal(statements,action_id):
            continue
        answer=answers.get(query_id)
        if answer is None:
            add_unresolved(unresolved,'Disposal window '+query_id+' was not semantically resolved.')
            continue
        choice=answer.get('choice')
        if choice not in ('endpoint_only','request_only','endpoint_or_request'):
            add_unresolved(unresolved,'Disposal window '+query_id+' remains unknown.')
            continue
        if not exact_grounding(answer,ids,byid):
            add_unresolved(unresolved,'Disposal window '+query_id+' lacks exact current evidence.')
            continue
        action_unit=byid.get(action_id)
        action_text=unit_text(action_unit).casefold() if action_unit is not None else ''
        full_text=window_text(ids,byid).casefold()
        do_return='return' in action_text
        do_destroy=('destroy' in action_text or 'destruct' in action_text) and 'not destroyed' not in action_text
        trigger=trigger_from_choice(choice,full_text)
        if trigger is None or (not do_return and not do_destroy):
            add_unresolved(unresolved,'Disposal window '+query_id+' lacks a complete source-grounded action or trigger.')
            continue
        split_clause=len(ids)>1 and not endpoint_trigger(action_text) and not request_trigger(action_text)
        information=disposal_information(action_text,split_clause)
        if do_return and do_destroy:
            action=['action_alternative',['return_to',information,['disclosing_party']],['destroy',information]]
        elif do_return:
            action=['return_to',information,['disclosing_party']]
        else:
            action=['destroy',information]
        term=['disposal_obligation',['receiving_party'],action,trigger,['no_exceptions']]
        add_statement(statements,term,ids)
    complete=bool(source_output.get('complete',False)) and not unresolved
    return {'statements':statements,'complete':complete,'unresolved':unresolved}

